<template>
  <section class="engagement-shell">
    <header class="engagement-intro">
      <div>
        <p class="engagement-kicker">Peshkash engagement</p>
        <h2>Bring people back, thoughtfully.</h2>
      </div>
    </header>

    <div v-if="!vendorId" class="engagement-empty"><i class="bi bi-building"></i><div><strong>Select a vendor</strong><p>Campaign audiences are matched from Peshkash subscribers who interacted with that vendor.</p></div></div>
    <div v-else-if="loading" class="engagement-loading"><span></span><span></span><span></span></div>
    <div v-else-if="error" class="engagement-empty"><i class="bi bi-cloud-slash"></i><div><strong>Could not load Engage</strong><p>{{ error }}</p></div><button class="eg-link" @click="load">Try again</button></div>

    <template v-else-if="overview">
      <nav class="engagement-tabs" aria-label="Engagement workspace"><button type="button" :class="{active:activeSection==='campaigns'}" @click="activeSection='campaigns'"><i class="bi bi-megaphone"></i> Campaigns</button><button type="button" :class="{active:activeSection==='recipients'}" @click="openRecipients"><i class="bi bi-people"></i> Recipients</button><button type="button" :class="{active:activeSection==='history'}" @click="activeSection='history'"><i class="bi bi-clock-history"></i> History</button></nav>

      <section v-if="activeSection==='campaigns'&&!composerOpen" class="workspace-page">
        <header class="workspace-page-head"><div><p class="engagement-kicker">Campaign management</p><h3>Campaigns ready to work on</h3><span>Create, edit, review recipients and send from one place.</span></div><button type="button" class="eg-primary" @click="startNewCampaign"><i class="bi bi-plus-lg"></i> New campaign</button></header>
        <p v-if="savedMessage" class="workspace-notice" role="status">{{ savedMessage }}</p>
        <div v-if="managedCampaigns.length" class="management-list">
          <article v-for="campaign in managedCampaigns" :key="campaign.id"><span class="campaign-icon"><i :class="campaign.channel==='push'?'bi bi-bell':'bi bi-whatsapp'"></i></span><div><strong>{{ campaign.title }}</strong><p>{{ campaign.recipientCount }} recipients · {{ campaign.audienceLabel }}</p><small>Opens {{ campaign.destinationPath }}</small></div><span class="draft-pill">{{ campaign.status }}</span><div class="management-actions"><button type="button" class="eg-link" @click="toggleCampaignRecipients(campaign)">Recipients</button><button type="button" class="eg-link" @click="editCampaign(campaign)">Edit</button><button v-if="confirmCampaignId!==campaign.id" type="button" class="eg-primary" :disabled="!providerReady(campaign.channel)||!campaign.recipientCount" @click="confirmCampaignId=campaign.id">Send</button><template v-else><button type="button" class="eg-primary" @click="sendCampaign(campaign)">Confirm send</button><button type="button" class="eg-link" @click="confirmCampaignId=null">Cancel</button></template></div></article>
          <div v-if="expandedCampaignId" class="management-recipient-panel"><p v-if="campaignRecipientsLoading===expandedCampaignId" class="recipient-loading">Loading recipients…</p><div v-else class="recipient-list"><div v-for="recipient in campaignRecipients[expandedCampaignId]||[]" :key="recipient.key" class="saved-recipient-row"><i :class="deliveryIcon(recipient.deliveryStatus)"></i><span><strong>{{ recipient.phone || recipient.maskedPhone }}</strong><small>{{ recipient.origin }} · {{ recipientSummary(recipient) }}</small></span><em :class="['delivery-state',recipient.deliveryStatus]">{{ deliveryLabel(recipient.deliveryStatus) }}</em></div></div></div>
        </div>
        <div v-else class="campaign-empty">No drafts need attention. Start a new campaign when you are ready.</div>
      </section>

      <div v-if="activeSection==='campaigns'&&composerOpen" class="engagement-grid">
        <form class="composer" @submit.prevent="saveDraft">
          <button type="button" class="wizard-close" @click="closeComposer"><i class="bi bi-arrow-left"></i> Campaigns</button>
          <div class="section-heading"><div><p class="engagement-kicker">{{ editingCampaignId?'Edit campaign':'New campaign' }}</p><h3>{{ wizardHeadings[wizardStep-1] }}</h3></div><span>Step {{ wizardStep }} of 3</span></div>
          <nav class="campaign-steps" aria-label="Campaign steps"><button v-for="(step,index) in wizardHeadings" :key="step" type="button" :class="{active:wizardStep===index+1,done:wizardStep>index+1}" @click="goToStep(index+1)"><span>{{ wizardStep>index+1?'✓':index+1 }}</span>{{ step }}</button></nav>

          <div v-if="wizardStep===1" class="wizard-panel">
            <label><span>Channel</span><select v-model="draft.channel"><option value="whatsapp">WhatsApp</option><option value="push">Peshkash push</option></select></label>
            <label><span>Starting point</span><select v-model="draft.templateKey" @change="applyTemplate"><option value="new_collection">New collection</option><option value="event_reminder">Event reminder</option><option value="saved_followup">Saved-item follow-up</option><option value="custom">Write my own</option></select></label>
            <label><span>Internal campaign name</span><input v-model.trim="draft.title" maxlength="120" placeholder="September collection rollout" /></label>
            <label><span>Message</span><textarea v-model.trim="draft.message" rows="7" maxlength="1200" placeholder="Write a concise, useful update..."></textarea><small>{{ draft.message.length }}/1200</small></label>
          </div>

          <fieldset v-else-if="wizardStep===2" class="audience-builder wizard-panel">
            <legend class="sr-only">Recipients</legend>
            <div class="audience-guidance"><strong>Start with an audience</strong><p>Choose a meaningful source. You can review and fine-tune the people before continuing.</p></div>
            <label class="audience-intent"><span>Audience source</span><select v-model="audienceChoice">
              <option value="all:">Everyone who engaged with {{ vendorName || 'this vendor' }}</option>
              <optgroup label="By behaviour"><option v-for="option in audiencePreview?.options.lists || []" :key="`list:${option.id}`" :value="`list:${option.id}`">{{ option.name }}</option></optgroup>
              <optgroup v-if="audiencePreview?.options.events.length" label="By event"><option v-for="option in audiencePreview.options.events" :key="`event:${option.id}`" :value="`event:${option.id}`">Event: {{ option.name }}</option></optgroup>
              <optgroup v-if="audiencePreview?.options.collections.length" label="By collection"><option v-for="option in audiencePreview.options.collections" :key="`collection:${option.id}`" :value="`collection:${option.id}`">Collection: {{ option.name }}</option></optgroup>
              <optgroup v-if="audiencePreview?.options.products.length" label="By product"><option v-for="option in audiencePreview.options.products" :key="`product:${option.id}`" :value="`product:${option.id}`">Product: {{ option.name }}</option></optgroup>
              <optgroup label="By discovery source"><option v-for="option in audiencePreview?.options.sources || []" :key="`source:${option.id}`" :value="`source:${option.id}`">{{ option.name }}</option></optgroup>
              <option value="custom:">Custom list — choose people</option>
            </select></label>
            <section class="recipient-workspace">
              <header class="recipient-workspace-head"><div><span>Your recipient list</span><strong>{{ recipientCount }} selected</strong><small>{{ audienceModeDescription }}</small></div><div><button v-if="audienceFilter.mode!=='custom'" type="button" class="eg-link" @click="customizeAudience"><i class="bi bi-pencil"></i> Fine-tune</button><button v-else type="button" class="eg-link" @click="addPersonOpen=!addPersonOpen"><i class="bi bi-person-plus"></i> Add person</button></div></header>
              <div v-if="audienceFilter.mode==='custom'&&addPersonOpen" class="add-recipient-inline"><input v-model.trim="manualPhone" inputmode="tel" placeholder="Enter exact phone number" @keyup.enter.prevent="addEligibleRecipient" /><button type="button" class="eg-primary" :disabled="checkingRecipient||!manualPhone" @click="addEligibleRecipient">{{ checkingRecipient?'Checking…':'Add' }}</button><button type="button" class="eg-link" @click="addPersonOpen=false;recipientCheckMessage=''">Cancel</button><p v-if="recipientCheckMessage" :class="{error:recipientCheckError}">{{ recipientCheckMessage }}</p></div>
              <div class="recipient-toolbar"><label><i class="bi bi-search"></i><input v-model.trim="audienceSearch" type="search" placeholder="Find someone in this list" /></label><div v-if="audienceFilter.mode==='custom'"><button type="button" @click="selectAllRecipients">Select all</button><button type="button" @click="clearRecipients">Clear</button></div></div>
              <div v-if="audienceLoading" class="recipient-loading">Building audience…</div>
              <div v-else-if="filteredRecipients.length" class="recipient-list">
                <label v-for="recipient in filteredRecipients" :key="recipient.key" class="recipient-row">
                  <input v-if="audienceFilter.mode==='custom'" type="checkbox" :checked="selectedRecipientKeys.has(recipient.key)" @change="toggleRecipient(recipient.key,($event.target as HTMLInputElement).checked)" />
                  <i v-else class="bi bi-check-circle-fill"></i>
                  <span><strong>{{ recipient.phone || recipient.maskedPhone }}</strong><small>{{ recipient.origin || recipientSummary(recipient) }}</small></span>
                  <time>{{ recipient.lastInteraction ? formatRelative(recipient.lastInteraction) : 'No vendor activity' }}</time>
                </label>
              </div>
              <p v-else class="recipient-empty">No consented recipients match this audience.</p>
              <footer class="recipient-guard"><i class="bi bi-shield-check"></i><span>Only people who opted in to {{ draft.channel==='push'?'Peshkash notifications':'WhatsApp updates' }} can be selected.</span></footer>
            </section>
          </fieldset>
          <div v-else-if="wizardStep===3" class="wizard-panel destination-step">
            <div class="audience-guidance"><strong>Where should people land?</strong><p>This is the page that opens when the push notification is tapped.</p></div>
            <label><span>Destination page</span><select v-model="draft.destinationPath"><option value="/home/saved">Saved collection</option><option value="/home/history">Activity history</option><optgroup v-if="destinationOptions.length" label="Events, collections and products"><option v-for="option in destinationOptions" :key="`${option.path}:${option.id}`" :value="option.path">{{ option.name }}</option></optgroup></select></label>
            <div class="destination-preview"><span><i class="bi bi-box-arrow-up-right"></i></span><div><small>Notification opens</small><strong>{{ destinationLabel }}</strong><code>{{ draft.destinationPath }}</code></div></div>
          </div>
          <div v-else class="wizard-panel review-step">
            <dl><div><dt>Campaign</dt><dd>{{ draft.title }}</dd></div><div><dt>Channel</dt><dd>{{ draft.channel==='push'?'Peshkash push':'WhatsApp' }}</dd></div><div><dt>Audience</dt><dd>{{ recipientCount }} recipients · {{ audienceModeDescription }}</dd></div><div><dt>Opens</dt><dd>{{ destinationLabel }}</dd></div></dl>
            <div class="consent-note"><i class="bi bi-shield-check"></i><p><strong>Consent-safe audience</strong><br>Every recipient is rechecked for active consent before each send.</p></div>
          </div>

          <div class="composer-actions"><button v-if="wizardStep>1" type="button" class="eg-link" @click="wizardStep--">Back</button><button v-if="wizardStep<4" type="button" class="eg-primary" :disabled="!canContinue" @click="wizardStep++">Continue</button><button v-else class="eg-primary" :disabled="saving || !draft.title || !draft.message || !recipientCount">{{ saving ? 'Saving…' : editingCampaignId?'Save changes':'Save campaign draft' }}</button></div>
          <p v-if="savedMessage" class="saved-message" role="status">{{ savedMessage }}</p>
        </form>

        <aside class="message-preview">
          <p class="preview-label">Recipient preview</p>
          <div class="phone-preview">
            <header><span class="sender-avatar">P</span><div><strong>Peshkash Updates</strong><small>Business account</small></div></header>
            <div class="message-bubble"><p>{{ draft.message || 'Your campaign message will appear here.' }}</p><a href="#" @click.prevent>{{ destinationLabel }}</a><time>10:42</time></div>
            <p class="vendor-context">Update from {{ vendorName }}</p>
          </div>
        </aside>
      </div>

      <section v-if="activeSection==='recipients'" class="workspace-page">
        <header class="workspace-page-head"><div><p class="engagement-kicker">Recipient directory</p><h3>Eligible subscribers</h3><span>People who can currently receive a campaign on the selected channel.</span></div><select v-model="directoryChannel" @change="loadRecipientDirectory"><option value="push">Peshkash notifications</option><option value="whatsapp">WhatsApp</option></select></header>
        <label class="directory-search"><i class="bi bi-search"></i><input v-model.trim="directorySearch" type="search" placeholder="Search by masked number or activity" /></label>
        <div v-if="directoryLoading" class="recipient-loading">Loading eligible subscribers…</div><div v-else-if="filteredDirectory.length" class="directory-list"><article v-for="recipient in filteredDirectory" :key="recipient.key"><span class="recipient-avatar"><i class="bi bi-person"></i></span><div><strong>{{ recipient.phone || recipient.maskedPhone }}</strong><p>{{ recipient.origin }}<template v-if="recipientSummary(recipient)"> · {{ recipientSummary(recipient) }}</template></p></div><span class="eligible-mark"><i class="bi bi-check-circle-fill"></i> Eligible</span><time>{{ recipient.lastInteraction?formatRelative(recipient.lastInteraction):'No vendor activity' }}</time></article></div><div v-else class="campaign-empty">No eligible subscribers found for this channel.</div>
      </section>

      <section v-if="activeSection==='history'" class="campaign-list workspace-page">
        <div class="section-heading"><div><p class="engagement-kicker">Campaign history</p><h3>Sent campaigns</h3></div><span>{{ historyCampaigns.length }} total</span></div>
        <div v-if="historyCampaigns.length" class="campaign-table">
          <div v-for="campaign in historyCampaigns" :key="campaign.id" class="campaign-entry">
            <article>
              <span class="campaign-icon"><i :class="campaign.channel === 'whatsapp' ? 'bi bi-whatsapp' : 'bi bi-bell'"></i></span>
              <div><strong>{{ campaign.title }}</strong><p>{{ campaign.message }}</p></div>
              <button type="button" class="campaign-audience" @click="toggleCampaignRecipients(campaign)">{{ campaign.recipientCount }} recipients · {{ campaign.audienceLabel }}</button>
              <span class="draft-pill">{{ campaign.status }}</span>
            <time>{{ formatDate(campaign.lastSentAt || campaign.createdAt) }}</time>
            <div class="campaign-send">
              <button type="button" class="eg-link" :disabled="campaign.status==='processing'" @click="reuseCampaign(campaign)"><i class="bi bi-arrow-repeat"></i> Edit &amp; send again</button>
            </div>
            </article>
            <div v-if="expandedCampaignId===campaign.id" class="campaign-recipient-panel">
              <header><div><strong>{{ campaign.audienceLabel }}</strong><small>Opens {{ campaign.destinationPath }}</small></div><button type="button" class="eg-link" @click="expandedCampaignId=null">Close</button></header>
              <p v-if="campaignRecipientsLoading===campaign.id" class="recipient-loading">Loading saved recipient list…</p>
              <div v-else-if="campaignRecipients[campaign.id]?.length" class="recipient-list">
                <div v-for="recipient in campaignRecipients[campaign.id]" :key="recipient.key" class="saved-recipient-row"><i :class="deliveryIcon(recipient.deliveryStatus)"></i><span><strong>{{ recipient.phone || recipient.maskedPhone }} <em :class="['delivery-state',recipient.deliveryStatus]">{{ deliveryLabel(recipient.deliveryStatus) }}</em></strong><small>{{ recipient.origin }} · {{ recipientSummary(recipient) }}</small><small v-if="recipient.deliveryError" class="delivery-error">{{ recipient.deliveryError }}</small></span><time>{{ recipient.attemptedAt?formatRelative(recipient.attemptedAt):formatRelative(recipient.lastInteraction) }}</time></div>
              </div>
              <p v-else class="recipient-empty">No recipients were saved with this campaign.</p>
            </div>
          </div>
        </div>
        <div v-else class="campaign-empty">Sent campaigns will appear here.</div>
        <p v-if="deliveryMessage" class="saved-message" role="status">{{ deliveryMessage }}</p>
      </section>
    </template>
  </section>
</template>

<script setup lang="ts">
import axios from 'axios'
import { computed, reactive, ref, watch } from 'vue'
import { API_BASE_URL } from '../../config'

type AudienceMode='all'|'list'|'collection'|'event'|'product'|'source'|'custom'
type AudienceFilter={mode:AudienceMode;value:string|null;recipientKeys:string[]}
type AudienceOption={id:number|string;name:string;path?:string}
type AudienceRecipient={key:string;phone?:string;maskedPhone:string;lastInteraction:string|null;activityCount:number;actions:string[];events:string[];collections:string[];products:string[];selected?:boolean;origin?:string;deliveryStatus?:'not_sent'|'sending'|'sent'|'failed';attemptedAt?:string|null;deliveryError?:string|null}
type AudiencePreview={mode:AudienceMode;total:number;eligibleTotal:number;recipients:AudienceRecipient[];options:{events:AudienceOption[];collections:AudienceOption[];products:AudienceOption[];lists:AudienceOption[];sources:AudienceOption[]}}
type Campaign = { id:number;channel:'whatsapp'|'push';title:string;message:string;templateKey:string|null;status:string;recipientCount:number;audienceFilter:AudienceFilter;audienceLabel:string;destinationPath:string;sendCount:number;lastSentAt:string|null;createdAt:string }
type Overview = { sender:{name:string;whatsapp:'configured'|'not_configured';push:'configured'|'not_configured'};audience:{knownUsers:number;recentlyActive:number;engagedUsers:number;whatsappOptedIn:number;pushOptedIn:number};campaigns:Campaign[] }
const props=defineProps<{vendorId?:number;vendorName?:string}>()
const loading=ref(false),saving=ref(false),error=ref(''),savedMessage=ref(''),deliveryMessage=ref(''),overview=ref<Overview|null>(null)
const activeSection=ref<'campaigns'|'recipients'|'history'>('campaigns'),composerOpen=ref(false),editingCampaignId=ref<number|null>(null)
const directoryChannel=ref<'push'|'whatsapp'>('push'),directoryRecipients=ref<AudienceRecipient[]>([]),directoryLoading=ref(false),directorySearch=ref('')
const confirmCampaignId=ref<number|null>(null),sendingCampaignId=ref<number|null>(null)
const expandedCampaignId=ref<number|null>(null),campaignRecipientsLoading=ref<number|null>(null),campaignRecipients=ref<Record<number,AudienceRecipient[]>>({})
const audiencePreview=ref<AudiencePreview|null>(null),audienceLoading=ref(false),audienceSearch=ref(''),selectedRecipientKeys=ref(new Set<string>())
const wizardStep=ref(1),wizardHeadings=['Write message','Choose recipients','Set destination','Review & save']
const manualPhone=ref(''),checkingRecipient=ref(false),recipientCheckMessage=ref(''),recipientCheckError=ref(false),addPersonOpen=ref(false),manualRecipients=ref<AudienceRecipient[]>([])
const audienceFilter=reactive<{mode:AudienceMode;value:string|null}>({mode:'all',value:null})
const templates:Record<string,string>={new_collection:'A new collection from {{vendor}} is now live on Peshkash. Explore it here:',event_reminder:'A reminder from {{vendor}}: your Peshkash experience is coming up. View the details here:',saved_followup:'Something you saved from {{vendor}} is waiting for another look. Return to your collection here:',custom:''}
const draft=reactive<{channel:'whatsapp'|'push';templateKey:string;title:string;message:string;destinationPath:string}>({channel:'whatsapp',templateKey:'new_collection',title:'',message:'',destinationPath:'/home/saved'})
const recipientCount=computed(()=>audienceFilter.mode==='custom'?selectedRecipientKeys.value.size:audiencePreview.value?.total??0)
const managedCampaigns=computed(()=>(overview.value?.campaigns||[]).filter(campaign=>campaign.status==='draft'||campaign.status==='failed'))
const historyCampaigns=computed(()=>(overview.value?.campaigns||[]).filter(campaign=>campaign.sendCount>0||['sent','partial','processing'].includes(campaign.status)))
const filteredDirectory=computed(()=>{const query=directorySearch.value.toLowerCase();return query?directoryRecipients.value.filter(recipient=>[recipient.phone||recipient.maskedPhone,recipient.origin||'',...recipient.events,...recipient.collections,...recipient.products,...recipient.actions].some(value=>value.toLowerCase().includes(query))):directoryRecipients.value})
const canContinue=computed(()=>wizardStep.value===1?Boolean(draft.title&&draft.message):wizardStep.value===2?recipientCount.value>0:true)
const audienceChoice=computed({get:()=>`${audienceFilter.mode}:${audienceFilter.value||''}`,set:(choice:string)=>{const [mode,value='']=choice.split(':');audienceFilter.mode=mode as AudienceMode;audienceFilter.value=value||null;selectedRecipientKeys.value=new Set();addPersonOpen.value=false;recipientCheckMessage.value='';loadAudience()}})
const allNamedOptions=computed(()=>(audiencePreview.value?[
  ...audiencePreview.value.options.lists.map(option=>({mode:'list',...option})),...audiencePreview.value.options.events.map(option=>({mode:'event',...option})),
  ...audiencePreview.value.options.collections.map(option=>({mode:'collection',...option})),...audiencePreview.value.options.products.map(option=>({mode:'product',...option})),
  ...audiencePreview.value.options.sources.map(option=>({mode:'source',...option})),]:[]))
const audienceModeDescription=computed(()=>audienceFilter.mode==='all'?'Everyone eligible who interacted with this vendor':audienceFilter.mode==='custom'?'A hand-picked subset of eligible subscribers':allNamedOptions.value.find(option=>option.mode===audienceFilter.mode&&String(option.id)===audienceFilter.value)?.name||'Selected audience')
const destinationOptions=computed(()=>{const options=audiencePreview.value?.options;if(!options)return[];return[...options.events.map(option=>({...option,name:`Event: ${option.name}`})),...options.collections.map(option=>({...option,name:`Collection: ${option.name}`})),...options.products.map(option=>({...option,name:`Product: ${option.name}`}))].filter(option=>option.path)})
const destinationLabel=computed(()=>destinationOptions.value.find(option=>option.path===draft.destinationPath)?.name||(draft.destinationPath==='/home/saved'?'View saved items':draft.destinationPath==='/home/history'?'View activity':'Open Peshkash'))
const managedRecipients=computed(()=>{const rows=[...(audiencePreview.value?.recipients||[]),...manualRecipients.value];return[...new Map(rows.map(row=>[row.key,row])).values()]})
const filteredRecipients=computed(()=>{const q=audienceSearch.value.toLowerCase();const rows=managedRecipients.value;return q?rows.filter(recipient=>[recipient.phone||recipient.maskedPhone,...recipient.events,...recipient.collections,...recipient.products,...recipient.actions].some(value=>value.toLowerCase().includes(q))):rows})
let audienceRequest=0
function providerReady(channel:'whatsapp'|'push'){return channel==='whatsapp'?overview.value?.sender.whatsapp==='configured':overview.value?.sender.push==='configured'}
function applyTemplate(){if(draft.templateKey!=='custom')draft.message=templates[draft.templateKey].replace('{{vendor}}',props.vendorName||'this vendor')}
async function load(){if(!props.vendorId){overview.value=null;return}loading.value=true;error.value='';try{overview.value=(await axios.get<Overview>(`${API_BASE_URL}/engagement/overview`,{params:{vendorId:props.vendorId}})).data;if(!draft.message)applyTemplate();await loadAudience()}catch(e:any){error.value=e?.response?.data?.error||'Please try again.'}finally{loading.value=false}}
async function loadAudience(){if(!props.vendorId)return;const request=++audienceRequest;audienceLoading.value=true;try{const params:Record<string,string|number>={vendorId:props.vendorId,channel:draft.channel,mode:audienceFilter.mode};if(audienceFilter.value)params.value=audienceFilter.value;if(audienceFilter.mode==='custom'&&selectedRecipientKeys.value.size)params.recipientKeys=[...selectedRecipientKeys.value].join(',');const result=(await axios.get<AudiencePreview>(`${API_BASE_URL}/engagement/audience`,{params})).data;if(request!==audienceRequest)return;audiencePreview.value=result}catch(e:any){if(request===audienceRequest){audiencePreview.value=null;savedMessage.value=e?.response?.data?.error||'Could not build this audience.'}}finally{if(request===audienceRequest)audienceLoading.value=false}}
function currentAudienceFilter():AudienceFilter{return{mode:audienceFilter.mode,value:audienceFilter.value,recipientKeys:audienceFilter.mode==='custom'?[...selectedRecipientKeys.value]:[]}}
async function saveDraft(){if(!props.vendorId||wizardStep.value!==4||!canContinue.value)return;saving.value=true;savedMessage.value='';try{const payload={vendorId:props.vendorId,...draft,audienceFilter:currentAudienceFilter()};const campaign=editingCampaignId.value?(await axios.patch<Campaign>(`${API_BASE_URL}/engagement/campaigns/${editingCampaignId.value}`,payload)).data:(await axios.post<Campaign>(`${API_BASE_URL}/engagement/campaigns`,payload)).data;if(overview.value){const index=overview.value.campaigns.findIndex(row=>row.id===campaign.id);if(index>=0)overview.value.campaigns.splice(index,1,campaign);else overview.value.campaigns.unshift(campaign)}delete campaignRecipients.value[campaign.id];if(expandedCampaignId.value===campaign.id)expandedCampaignId.value=null;savedMessage.value=`${editingCampaignId.value?'Campaign updated':'Draft saved'} for ${campaign.recipientCount} recipient${campaign.recipientCount===1?'':'s'}.`;editingCampaignId.value=null;composerOpen.value=false;wizardStep.value=1}catch(e:any){savedMessage.value=e?.response?.data?.error||'Could not save this draft.'}finally{saving.value=false}}
async function sendCampaign(campaign:Campaign){if(!props.vendorId||sendingCampaignId.value)return;const previousStatus=campaign.status;sendingCampaignId.value=campaign.id;deliveryMessage.value='';try{await loadCampaignRecipients(campaign.id);expandedCampaignId.value=campaign.id;campaign.status='processing';campaignRecipients.value={...campaignRecipients.value,[campaign.id]:(campaignRecipients.value[campaign.id]||[]).map(recipient=>({...recipient,deliveryStatus:'sending'}))};const result=(await axios.post(`${API_BASE_URL}/engagement/campaigns/${campaign.id}/send`,{vendorId:props.vendorId})).data;campaign.status=result.status;campaign.sendCount+=1;campaign.lastSentAt=new Date().toISOString();deliveryMessage.value=`${result.delivered} message${result.delivered===1?'':'s'} accepted by the provider${result.failed?`; ${result.failed} failed`:''}.`;confirmCampaignId.value=null;await loadCampaignRecipients(campaign.id,true);activeSection.value='history'}catch(e:any){campaign.status=previousStatus;deliveryMessage.value=e?.response?.data?.error||'Could not send this campaign.';await loadCampaignRecipients(campaign.id,true).catch(()=>{})}finally{sendingCampaignId.value=null}}
function formatDate(value:string){return new Date(value).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function formatRelative(value:string|null){if(!value)return'No vendor activity';const ms=Date.now()-new Date(value).getTime(),hours=Math.floor(ms/3600000),days=Math.floor(ms/86400000);return hours<1?'Just now':hours<24?`${hours}h ago`:days<30?`${days}d ago`:formatDate(value)}
function recipientSummary(recipient:AudienceRecipient){return[recipient.events[0],recipient.collections[0],recipient.products?.[0],`${recipient.activityCount} interaction${recipient.activityCount===1?'':'s'}`].filter(Boolean).join(' · ')}
function deliveryLabel(status?:AudienceRecipient['deliveryStatus']){return status==='sent'?'Accepted':status==='failed'?'Failed':status==='sending'?'Sending':'Not sent'}
function deliveryIcon(status?:AudienceRecipient['deliveryStatus']){return status==='sent'?'bi bi-check-circle-fill':status==='failed'?'bi bi-exclamation-circle-fill':status==='sending'?'bi bi-arrow-repeat':'bi bi-clock'}
function toggleRecipient(key:string,selected:boolean){const next=new Set(selectedRecipientKeys.value);if(selected)next.add(key);else next.delete(key);selectedRecipientKeys.value=next}
function selectAllRecipients(){selectedRecipientKeys.value=new Set(managedRecipients.value.map(recipient=>recipient.key))}
function clearRecipients(){selectedRecipientKeys.value=new Set()}
function resetComposer(){editingCampaignId.value=null;wizardStep.value=1;Object.assign(draft,{channel:'push',templateKey:'new_collection',title:'',message:'',destinationPath:'/home/saved'});applyTemplate();audienceFilter.mode='all';audienceFilter.value=null;selectedRecipientKeys.value=new Set();manualRecipients.value=[];recipientCheckMessage.value=''}
function startNewCampaign(){resetComposer();composerOpen.value=true;loadAudience()}
function closeComposer(){composerOpen.value=false;editingCampaignId.value=null;wizardStep.value=1}
async function editCampaign(campaign:Campaign){editingCampaignId.value=campaign.id;Object.assign(draft,{channel:campaign.channel,templateKey:campaign.templateKey||'custom',title:campaign.title,message:campaign.message,destinationPath:campaign.destinationPath});audienceFilter.mode=campaign.audienceFilter?.mode||'all';audienceFilter.value=campaign.audienceFilter?.value||null;selectedRecipientKeys.value=new Set(campaign.audienceFilter?.recipientKeys||[]);manualRecipients.value=[];wizardStep.value=1;composerOpen.value=true;await loadAudience()}
async function reuseCampaign(campaign:Campaign){editingCampaignId.value=null;savedMessage.value='';Object.assign(draft,{channel:campaign.channel,templateKey:campaign.templateKey||'custom',title:campaign.title,message:campaign.message,destinationPath:campaign.destinationPath});audienceFilter.mode=campaign.audienceFilter?.mode||'all';audienceFilter.value=campaign.audienceFilter?.value||null;selectedRecipientKeys.value=new Set(campaign.audienceFilter?.recipientKeys||[]);manualRecipients.value=[];wizardStep.value=1;activeSection.value='campaigns';composerOpen.value=true;await loadAudience()}
async function openRecipients(){activeSection.value='recipients';await loadRecipientDirectory()}
async function loadRecipientDirectory(){if(!props.vendorId)return;directoryLoading.value=true;try{directoryRecipients.value=(await axios.get(`${API_BASE_URL}/engagement/recipients`,{params:{vendorId:props.vendorId,channel:directoryChannel.value}})).data.recipients||[]}catch(e:any){deliveryMessage.value=e?.response?.data?.error||'Could not load recipients.'}finally{directoryLoading.value=false}}
function customizeAudience(){selectedRecipientKeys.value=new Set((audiencePreview.value?.recipients||[]).map(recipient=>recipient.key));audienceFilter.mode='custom';audienceFilter.value=null;addPersonOpen.value=false}
function goToStep(step:number){if(step<=wizardStep.value||(step===wizardStep.value+1&&canContinue.value))wizardStep.value=step}
async function addEligibleRecipient(){if(!props.vendorId||checkingRecipient.value||!manualPhone.value)return;checkingRecipient.value=true;recipientCheckMessage.value='';recipientCheckError.value=false;try{const result=(await axios.post(`${API_BASE_URL}/engagement/audience/eligible-recipient`,{vendorId:props.vendorId,channel:draft.channel,phone:manualPhone.value})).data;const recipient=result.recipient as AudienceRecipient;if(!managedRecipients.value.some(row=>row.key===recipient.key))manualRecipients.value=[...manualRecipients.value,recipient];toggleRecipient(recipient.key,true);manualPhone.value='';recipientCheckMessage.value=`${recipient.phone||recipient.maskedPhone} added.`}catch(e:any){recipientCheckError.value=true;recipientCheckMessage.value=e?.response?.data?.error||'Could not verify this recipient.'}finally{checkingRecipient.value=false}}
async function loadCampaignRecipients(campaignId:number,force=false){if(!props.vendorId||(!force&&campaignRecipients.value[campaignId]))return;campaignRecipientsLoading.value=campaignId;try{const result=(await axios.get(`${API_BASE_URL}/engagement/campaigns/${campaignId}/recipients`,{params:{vendorId:props.vendorId}})).data;campaignRecipients.value={...campaignRecipients.value,[campaignId]:result.recipients||[]}}finally{campaignRecipientsLoading.value=null}}
async function toggleCampaignRecipients(campaign:Campaign){if(expandedCampaignId.value===campaign.id){expandedCampaignId.value=null;return}expandedCampaignId.value=campaign.id;try{await loadCampaignRecipients(campaign.id,true)}catch(e:any){deliveryMessage.value=e?.response?.data?.error||'Could not load campaign recipients.'}}
watch(()=>props.vendorId,load,{immediate:true})
watch(()=>draft.channel,()=>{selectedRecipientKeys.value=new Set();manualRecipients.value=[];recipientCheckMessage.value='';loadAudience()})
</script>

